#!/usr/bin/env python3
"""Builds the component fixtures.

Outputs, in this directory:
- dependencies.pb and expected-bundle.txt: a bundle dependency record written by
  WriteDependencies.java with the Android Gradle Plugin's own generated protobuf classes
  (AGP 9.4.1), and what those classes read back from it;
- components.aab: ../android/bundle.aab with that record, AGP's app-metadata.properties, and
  metadata files under base/root/ (a version file, one naming a build task instead of a
  version, a pom.properties and a Google Play services client file);
- components.apk: ../android/code.apk (two DEX files) with the same kinds of metadata files at
  their APK paths, AGP's app-metadata.properties and a native library;
- expected-files.txt: the component each metadata file describes, written from the data below.

Needs a JDK (javac and java on PATH, or JAVA_HOME) and, in the Gradle cache (or AGP_JAR and
PROTOBUF_JAR), com.android.tools.build:gradle:9.4.1 and com.google.protobuf:protobuf-java:3.25.5.
"""

from __future__ import annotations

import glob
import os
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "android"))
import make_elf_fixtures  # noqa: E402

DATE = (2026, 1, 1, 0, 0, 0)
CACHE = Path.home() / ".gradle/caches/modules-2/files-2.1"
DEPENDENCIES = "BUNDLE-METADATA/com.android.tools.build.libraries/dependencies.pb"

# (path relative to the APK root or a bundle module's root/, contents, expected component as
# "group:name@version" or "group:name@-" without a version).
FILES = [
    ("META-INF/androidx.core_core.version", "1.15.0\n", "androidx.core:core@1.15.0"),
    (
        "META-INF/androidx.arch.core_core-runtime.version",
        "task ':arch:core:core-runtime:writeVersionFile' property 'version'",
        "androidx.arch.core:core-runtime@-",
    ),
    ("META-INF/kotlinx_coroutines_core.version", "1.10.1\n", "org.jetbrains.kotlinx:kotlinx-coroutines-core@1.10.1"),
    (
        "META-INF/maven/com.squareup.okio/okio/pom.properties",
        "#Generated by Maven\nversion=3.9.0\ngroupId=com.squareup.okio\nartifactId=okio\n",
        "com.squareup.okio:okio@3.9.0",
    ),
    (
        "play-services-basement.properties",
        "version=18.4.0\nclient=play-services-basement\nplay-services-basement_client=18.4.0\n",
        "com.google.android.gms:play-services-basement@18.4.0",
    ),
]
APP_METADATA = "appMetadataVersion=1.1\nandroidGradlePluginVersion=9.4.1\n"


def jar(environment: str, pattern: str) -> str:
    if os.environ.get(environment):
        return os.environ[environment]
    found = glob.glob(str(CACHE / pattern))
    if not found:
        raise SystemExit(f"{pattern} not in the Gradle cache; set {environment}")
    return found[0]


def write_zip(path: Path, entries: dict[str, bytes]) -> None:
    with zipfile.ZipFile(path, "w") as archive:
        for name in sorted(entries, key=lambda entry: (entry != "AndroidManifest.xml", entry)):
            info = zipfile.ZipInfo(name, date_time=DATE)
            info.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(info, entries[name])


def read_zip(path: Path) -> dict[str, bytes]:
    with zipfile.ZipFile(path) as archive:
        return {info.filename: archive.read(info) for info in archive.infolist() if not info.is_dir()}


def main() -> None:
    classpath = os.pathsep.join([
        jar("AGP_JAR", "com.android.tools.build/gradle/9.4.1/*/gradle-9.4.1.jar"),
        jar("PROTOBUF_JAR", "com.google.protobuf/protobuf-java/3.25.5/*/protobuf-java-3.25.5.jar"),
    ])
    with tempfile.TemporaryDirectory() as directory:
        work = Path(directory)
        subprocess.run(["javac", "-cp", classpath, "-d", work, HERE / "WriteDependencies.java"], check=True)
        subprocess.run(
            ["java", "-cp", f"{classpath}{os.pathsep}{work}", "WriteDependencies",
             HERE / "dependencies.pb", HERE / "expected-bundle.txt"],
            check=True,
        )
    record = (HERE / "dependencies.pb").read_bytes()

    bundle = read_zip(HERE.parent / "android/bundle.aab")
    bundle[DEPENDENCIES] = record
    bundle["BUNDLE-METADATA/com.android.tools.build.gradle/app-metadata.properties"] = APP_METADATA.encode()
    for path, text, _ in FILES:
        bundle[f"base/root/{path}"] = text.encode()
    write_zip(HERE / "components.aab", bundle)

    apk = read_zip(HERE.parent / "android/code.apk")
    apk["META-INF/com/android/build/gradle/app-metadata.properties"] = APP_METADATA.encode()
    for path, text, _ in FILES:
        apk[path] = text.encode()
    apk["lib/arm64-v8a/libsqlcipher.so"] = make_elf_fixtures.build(make_elf_fixtures.Library(name="libsqlcipher.so"))
    write_zip(HERE / "components.apk", apk)

    (HERE / "expected-files.txt").write_text("".join(f"{path}\t{expected}\n" for path, _, expected in FILES))
    print(f"wrote dependencies.pb, expected-bundle.txt, components.aab, components.apk, expected-files.txt in {HERE}")


if __name__ == "__main__":
    main()
